					},
				},
			},
		},
		{
			name: "OTLP HTTPS",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "https://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP GRPC",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "grpc://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
